{"path": "styles.css", "content": "/* Doggy Duty, LLC — landing page styles */
:root{
  --ink:#131209; --muted:#5c5b55; --line:#e4e3dd; --surface:#f6f5f0; --white:#fff;
  --primary:#ff6a00; --secondary:#1e90ff; --dark:#131209;
  --s25:2px; --s50:4px; --s75:8px; --s100:12px; --s200:16px; --s300:24px; --s400:32px;
  --s500:40px; --s600:48px; --s700:64px; --s800:80px; --s900:96px;
  --ease:cubic-bezier(0.32,0.72,0,1);
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--white);color:var(--ink);
  font-family:Poppins,Geist,system-ui,sans-serif;font-size:1rem;line-height:1.5rem;
  font-weight:400;text-wrap:pretty;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{margin:0;font-weight:600;text-wrap:balance;letter-spacing:-0.02em}
p{margin:0}
a{color:inherit;text-decoration:none}
ul{margin:0;padding:0;list-style:none}
img,svg{display:block;max-width:100%}
:focus-visible{outline:2px solid var(--secondary);outline-offset:2px;border-radius:4px}
.skip{position:absolute;left:-9999px;top:var(--s75);background:var(--ink);color:#fff;
  padding:var(--s75) var(--s100);border-radius:9999px;font-size:.875rem;line-height:1.25rem;z-index:80}
.skip:focus{left:var(--s300)}
.container{width:100%;max-width:1200px;margin:0 auto;padding:0 var(--s300)}
.section{padding:var(--s700) 0}
.section--surface{background:var(--surface)}
.section--dark{background:var(--dark);color:#fff}
.eyebrow{font-size:.875rem;line-height:1.25rem;font-weight:600;color:var(--primary);
  text-transform:uppercase;letter-spacing:.08em}
.h2{font-size:1.875rem;line-height:2.25rem}
.lede{font-size:1.125rem;line-height:1.75rem;color:var(--muted);max-width:680px}
.section--dark .lede{color:#b9b7ad}
.head{max-width:680px;margin-bottom:var(--s500);display:flex;flex-direction:column;gap:var(--s100)}
.muted{color:var(--muted)}
.small{font-size:.875rem;line-height:1.25rem}
.xs{font-size:.75rem;line-height:1rem}

/* buttons */
.btn{display:inline-flex;align-items:center;gap:var(--s75);padding:var(--s75) var(--s100);
  border-radius:9999px;font-size:1rem;line-height:1.5rem;font-weight:600;border:1px solid transparent;
  cursor:pointer;font-family:inherit;
  transition:all 700ms var(--ease)}
.btn i{font-size:1.125rem}
.btn--primary{background:var(--primary);color:#fff}
.btn--primary:hover{background:#e65f00;transform:translateY(-1px)}
.btn--primary:active{transform:scale(.98)}
.btn--dark{background:var(--ink);color:#fff}
.btn--dark:hover{background:#2a2818;transform:translateY(-1px)}
.btn--dark:active{transform:scale(.98)}
.btn--ghost{background:transparent;color:var(--ink);border-color:var(--line)}
.btn--ghost:hover{background:var(--white);border-color:var(--ink)}
.btn--ghost:active{transform:scale(.98)}
.btn--sm{font-size:.875rem;line-height:1.25rem}
.btn[disabled]{opacity:.55;cursor:not-allowed;transform:none}
.textlink{font-weight:600;border-bottom:1px solid var(--line);
  transition:border-color 700ms var(--ease),color 700ms var(--ease)}
.textlink:hover{border-color:var(--primary);color:var(--primary)}

/* nav */
.nav{position:fixed;top:var(--s300);left:0;right:0;z-index:60;display:flex;justify-content:center;
  pointer-events:none}
.nav__pill{pointer-events:auto;display:flex;align-items:center;gap:var(--s300);width:max-content;
  max-width:calc(100vw - 32px);padding:var(--s75) var(--s100);border:1px solid var(--line);
  border-radius:9999px;background:rgba(255,255,255,.82);backdrop-filter:blur(24px) saturate(1.4);
  box-shadow:0 12px 32px rgba(19,18,9,.08)}
.brand{display:flex;align-items:center;gap:var(--s75);font-weight:600;padding-left:var(--s75)}
.brand i{color:var(--primary);font-size:1.25rem}
.nav__links{display:none;align-items:center;gap:var(--s300);font-size:.875rem;line-height:1.25rem;
  font-weight:500}
.nav__links a{padding:var(--s50) 0;border-bottom:1px solid transparent;
  transition:all 700ms var(--ease)}
.nav__links a:hover{color:var(--primary)}
.nav__links a.is-current{border-bottom-color:var(--primary);font-weight:600}
.nav__cta{display:none}
.burger{position:relative;width:40px;height:40px;border:1px solid var(--line);border-radius:9999px;
  background:var(--white);cursor:pointer;transition:all 700ms var(--ease)}
.burger:hover{border-color:var(--ink)}
.burger:active{transform:scale(.96)}
.burger span{position:absolute;left:50%;width:16px;height:2px;background:var(--ink);border-radius:2px;
  transform:translateX(-50%);transition:all 700ms var(--ease)}
.burger span:nth-child(1){top:15px}
.burger span:nth-child(2){top:23px}
.nav.is-open .burger span:nth-child(1){top:19px;transform:translateX(-50%) rotate(45deg)}
.nav.is-open .burger span:nth-child(2){top:19px;transform:translateX(-50%) rotate(-45deg)}
.overlay{position:fixed;inset:0;z-index:50;background:rgba(255,255,255,.85);
  backdrop-filter:blur(64px) saturate(1.2);display:flex;flex-direction:column;justify-content:center;
  gap:var(--s300);padding:var(--s900) var(--s300);opacity:0;visibility:hidden;
  transition:opacity 700ms var(--ease),visibility 700ms var(--ease)}
.nav.is-open ~ .overlay{opacity:1;visibility:visible}
.overlay a{display:block;font-size:2.25rem;line-height:2.5rem;font-weight:600;overflow:hidden}
.overlay a span{display:block;transform:translateY(48px);opacity:0;
  transition:transform 800ms var(--ease),opacity 800ms var(--ease)}
.nav.is-open ~ .overlay a span{transform:translateY(0);opacity:1}
.overlay a:nth-child(1) span{transition-delay:100ms}
.overlay a:nth-child(2) span{transition-delay:150ms}
.overlay a:nth-child(3) span{transition-delay:200ms}
.overlay a:nth-child(4) span{transition-delay:250ms}
.overlay__foot{font-size:1rem;color:var(--muted);opacity:0;transition:opacity 800ms var(--ease) 300ms}
.nav.is-open ~ .overlay .overlay__foot{opacity:1}

/* hero */
.hero{padding:var(--s900) 0 var(--s700)}
.hero__grid{display:grid;gap:var(--s600);align-items:center}
.hero h1{max-width:680px;font-size:2.25rem;line-height:2.5rem;
  background:linear-gradient(90deg,#000 0%,#666 100%);-webkit-background-clip:text;
  background-clip:text;color:transparent}
.hero__sub{max-width:680px;margin-top:var(--s300);font-size:1.125rem;line-height:1.75rem;color:var(--muted)}
.hero__actions{display:flex;flex-wrap:wrap;align-items:center;gap:var(--s200);margin-top:var(--s400)}
.hero__proof{display:flex;align-items:center;gap:var(--s75);margin-top:var(--s300);
  font-size:.875rem;line-height:1.25rem;color:var(--muted)}
.hero__proof i{color:var(--primary);font-size:1.125rem}

/* panel (service log) */
.panel{border:1px solid var(--line);border-radius:16px;background:var(--white);padding:var(--s400);
  box-shadow:0 24px 60px rgba(19,18,9,.08)}
.panel__top{display:flex;align-items:center;justify-content:space-between;gap:var(--s200);
  padding-bottom:var(--s200);border-bottom:1px solid var(--line)}
.chip{display:inline-flex;align-items:center;gap:var(--s50);padding:var(--s25) var(--s75);
  border-radius:9999px;font-size:.75rem;line-height:1rem;font-weight:600;
  background:var(--surface);color:var(--muted)}
.chip--done{background:#eaf4ff;color:#0b5ea8}
.chip--live{background:#fff1e5;color:#a34400}
.log{display:flex;flex-direction:column}
.log__row{display:flex;align-items:center;justify-content:space-between;gap:var(--s200);
  padding:var(--s200) 0;border-bottom:1px solid var(--line)}
.log__row:last-child{border-bottom:0;padding-bottom:0}
.log__name{font-weight:600;font-size:.875rem;line-height:1.25rem}

/* cards + grids */
.grid{display:grid;gap:var(--s300)}
.card{border:1px solid var(--line);border-radius:16px;background:var(--white);padding:var(--s400);
  display:flex;flex-direction:column;gap:var(--s100);transition:all 700ms var(--ease)}
.card:hover{transform:translateY(-4px);box-shadow:0 20px 44px rgba(19,18,9,.09)}
.section--surface .card{background:var(--white)}
.card h3{font-size:1.25rem;line-height:1.75rem}
.icon{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;
  border-radius:9999px;background:#fff1e5;color:var(--primary);font-size:1.5rem;margin-bottom:var(--s100)}
.icon--blue{background:#eaf4ff;color:#0b5ea8}
.stats{display:grid;gap:var(--s300);border-top:1px solid var(--line);border-bottom:1px solid var(--line);
  padding:var(--s500) 0}
.stat__num{font-size:2.25rem;line-height:2.5rem;font-weight:600}
.stat__num span{color:var(--primary)}
.bullets{display:flex;flex-direction:column;gap:var(--s300)}
.bullets li{display:flex;gap:var(--s200);align-items:flex-start}
.bullets i{color:var(--primary);font-size:1.25rem;margin-top:var(--s25)}
.bullets b{font-weight:600}
.steps{counter-reset:step}
.step{position:relative}
.step__num{display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;
  border-radius:9999px;background:var(--ink);color:#fff;font-size:.875rem;line-height:1.25rem;
  font-weight:600;margin-bottom:var(--s100)}

/* tagline reveal */
.tagline{max-width:680px;font-size:2.25rem;line-height:2.75rem;font-weight:600;letter-spacing:-0.02em}
.tagline .w{color:rgba(255,255,255,.3);transition:color 800ms var(--ease)}
.tagline .w.on{color:#fff}

/* schedule picker */
.picker{display:flex;flex-wrap:wrap;gap:var(--s200)}
.picker button{padding:var(--s75) var(--s100);border-radius:9999px;border:1px solid var(--line);
  background:var(--white);font-family:inherit;font-size:.875rem;line-height:1.25rem;font-weight:600;
  cursor:pointer;transition:all 700ms var(--ease)}
.picker button:hover{border-color:var(--ink)}
.picker button:active{transform:scale(.98)}
.picker button[aria-pressed="true"]{background:var(--ink);color:#fff;border-color:var(--ink)}
.plan{margin-top:var(--s300);border:1px solid var(--line);border-radius:16px;background:var(--white);
  padding:var(--s400);min-height:200px}
.plan__empty{display:flex;flex-direction:column;align-items:flex-start;gap:var(--s100);color:var(--muted)}
.plan__empty i{font-size:1.5rem;color:var(--primary)}

/* quotes */
.quote{border:1px solid var(--line);border-radius:16px;background:var(--white);padding:var(--s400);
  display:flex;flex-direction:column;gap:var(--s300)}
.quote p{font-size:1.125rem;line-height:1.75rem}
.who{display:flex;align-items:center;gap:var(--s100)}
.avatar{width:40px;height:40px;border-radius:9999px;display:flex;align-items:center;
  justify-content:center;font-size:.875rem;font-weight:600;color:#fff;background:var(--ink)}
.avatar--o{background:var(--primary)}
.avatar--b{background:#0b5ea8}

/* faq */
.faq{display:flex;flex-direction:column;gap:var(--s200);max-width:820px}
.faq details{border:1px solid var(--line);border-radius:12px;background:var(--white);padding:var(--s300)}
.faq summary{display:flex;justify-content:space-between;gap:var(--s200);align-items:center;
  cursor:pointer;font-weight:600;list-style:none}
.faq summary::-webkit-details-marker{display:none}
.faq summary i{color:var(--primary);transition:transform 700ms var(--ease)}
.faq details[open] summary i{transform:rotate(45deg)}
.faq p{margin-top:var(--s200);color:var(--muted)}

/* form */
.form{border:1px solid var(--line);border-radius:16px;background:var(--white);padding:var(--s400);
  display:grid;gap:var(--s200)}
.field{display:flex;flex-direction:column;gap:var(--s50)}
.field label{font-size:.875rem;line-height:1.25rem;font-weight:600}
.field input,.field select,.field textarea{font-family:inherit;font-size:1rem;line-height:1.5rem;
  color:var(--ink);padding:var(--s75) var(--s100);border:1px solid var(--line);border-radius:8px;
  background:var(--white);transition:all 700ms var(--ease)}
.field input:hover,.field select:hover,.field textarea:hover{border-color:#c9c8c0}
.field .err{font-size:.75rem;line-height:1rem;color:#b0300b;min-height:1rem}
.field.is-bad input,.field.is-bad select{border-color:#b0300b}
.skel{display:none;flex-direction:column;gap:var(--s75)}
.skel span{display:block;height:12px;border-radius:4px;background:#eceb e5;background:#ecebe5;
  animation:pulse 1400ms var(--ease) infinite}
.skel span:nth-child(2){width:70%}
.skel span:nth-child(3){width:45%}
@keyframes pulse{0%,100%{background:#ecebe5}50%{background:#f7f6f1}}
.form.is-sending .skel{display:flex}
.ok{display:none;gap:var(--s75);align-items:flex-start;padding:var(--s200);border-radius:8px;
  background:#eaf4ff;color:#0b5ea8;font-size:.875rem;line-height:1.25rem}
.form.is-done .ok{display:flex}
.form.is-done .form__body{display:none}
.form__body{display:grid;gap:var(--s200)}

/* footer */
.footer{background:var(--dark);color:#b9b7ad;padding:var(--s700) 0 var(--s400)}
.footer a:hover{color:#fff}
.footer h4{color:#fff;font-size:.875rem;line-height:1.25rem;text-transform:uppercase;
  letter-spacing:.08em;margin-bottom:var(--s200)}
.footer__grid{display:grid;gap:var(--s500)}
.footer__col ul{display:flex;flex-direction:column;gap:var(--s75);font-size:.875rem;line-height:1.5rem}
.footer__bar{margin-top:var(--s600);padding-top:var(--s300);border-top:1px solid #272727;
  display:flex;flex-wrap:wrap;gap:var(--s200);justify-content:space-between;font-size:.75rem;line-height:1rem}
.legal{max-width:820px;display:flex;flex-direction:column;gap:var(--s200)}
.legal h3{font-size:1.125rem;line-height:1.75rem}

/* reveal */
.rv{opacity:0;transform:translateY(64px);filter:blur(12px);
  transition:opacity 800ms var(--ease),transform 800ms var(--ease),filter 800ms var(--ease)}
.rv.in{opacity:1;transform:translateY(0);filter:blur(0)}

@media (min-width:720px){
  .section{padding:var(--s900) 0}
  .h2{font-size:2.25rem;line-height:2.5rem}
  .hero h1{font-size:3rem;line-height:1.05}
  .tagline{font-size:3rem;line-height:1.2}
  .grid--2{grid-template-columns:repeat(2,1fr)}
  .grid--3{grid-template-columns:repeat(3,1fr)}
  .stats{grid-template-columns:repeat(3,1fr)}
  .form__row{display:grid;grid-template-columns:1fr 1fr;gap:var(--s200)}
  .footer__grid{grid-template-columns:1.4fr 1fr 1fr 1fr}
}
@media (min-width:1000px){
  .nav__links,.nav__cta{display:flex}
  .burger{display:none}
  .hero{padding:var(--s900) 0}
  .hero h1{font-size:3.75rem}
  .hero__grid{grid-template-columns:1.05fr .95fr}
  .grid--4{grid-template-columns:repeat(4,1fr)}
  .split{display:grid;grid-template-columns:1fr 1fr;gap:var(--s700);align-items:start}
}
@media (prefers-reduced-motion:reduce){
  *{transition-duration:1ms!important;animation:none!important}
  .rv{opacity:1;transform:none;filter:none}
}
"}

