.brand{display:flex; align-items:center; gap:var(--sp-75); padding-left:var(--sp-75);
  font-weight:600; font-size:1rem; line-height:24px; text-decoration:none}
.brand i{color:var(--primary); font-size:1.5rem}
.navlinks{display:none; align-items:center; gap:var(--sp-200)}
@media(min-width:900px){.navlinks{display:flex}}
.navlinks a{font-size:0.875rem; line-height:20px; font-weight:500; text-decoration:none;
  color:var(--muted); padding:var(--sp-50) var(--sp-75); border-radius:var(--r-full);
  transition:all .4s var(--ease)}
.navlinks a:hover{color:var(--ink); background:rgba(19,18,9,.05)}
.navlinks a.is-current{color:var(--ink); background:rgba(255,106,0,.12)}
.burger{display:grid; place-items:center; width:40px; height:40px; border:1px solid var(--line);
  border-radius:var(--r-full); background:var(--white); cursor:pointer; position:relative}
@media(min-width:900px){.burger{display:none}}
.burger span{position:absolute; left:11px; width:18px; height:2px; background:var(--ink);
  border-radius:var(--r-full); transition:transform .7s var(--ease), opacity .5s var(--ease)}
.burger span:nth-child(1){transform:translateY(-5px)}
.burger span:nth-child(2){transform:translateY(5px)}
body.menu-open .burger span:nth-child(1){transform:rotate(45deg)}
body.menu-open .burger span:nth-child(2){transform:rotate(-45deg)}

.sheet{position:fixed; inset:0; z-index:55; display:grid; align-content:center; justify-items:start;
  gap:var(--sp-300); padding:var(--sp-800) var(--sp-400);
  background:rgba(255,255,255,.80); backdrop-filter:blur(64px) saturate(1.4);
  opacity:0; visibility:hidden; transition:opacity .7s var(--ease), visibility .7s var(--ease)}
body.menu-open .sheet{opacity:1; visibility:visible}
.sheet a{font-size:2.25rem; line-height:40px; font-weight:600; text-decoration:none;
  opacity:0; transform:translateY(48px); transition:all .7s var(--ease)}
body.menu-open .sheet a{opacity:1; transform:translateY(0)}
.sheet a:nth-child(1){transition-delay:.10s}
.sheet a:nth-child(2){transition-delay:.15s}
.sheet a:nth-child(3){transition-delay:.20s}
.sheet a:nth-child(4){transition-delay:.25s}
.sheet .small{opacity:0; transition:opacity .7s var(--ease) .3s}
body.menu-open .sheet .small{opacity:1}

/* ---------- hero ---------- */
.hero{padding:var(--sp-900) 0 var(--sp-700)}
@media(min-width:768px){.hero{padding:160px 0 var(--sp-900)}}
.hero-grid{display:grid; gap:var(--sp-600); align-items:center}
@media(min-width:1000px){.hero-grid{grid-template-columns:1.05fr .95fr; gap:var(--sp-700)}}
.hero h1{font-size:2.25rem; line-height:40px; max-width:680px;
  background:linear-gradient(90deg,#000000 0%,#666666 100%);
  -webkit-background-clip:text; background-clip:text; color:transparent}
@media(min-width:640px){.hero h1{font-size:3rem; line-height:1}}
@media(min-width:1000px){.hero h1{font-size:3.75rem; line-height:1}}
.hero .lead{max-width:680px}
.cta-row{display:flex; flex-wrap:wrap; align-items:center; gap:var(--sp-200)}
.badge{display:inline-flex; align-items:center; gap:var(--sp-75); padding:var(--sp-50) var(--sp-100);
  border:1px solid var(--line); border-radius:var(--r-full); background:var(--white);
  font-size:0.875rem; line-height:20px; font-weight:500}
.badge i{color:var(--primary)}

/* ---------- cards ---------- */
.card{background:var(--white); border:1px solid var(--line); border-radius:var(--r-2xl);
  padding:var(--sp-400); transition:all .6s var(--ease)}
.card--hover:hover{transform:translateY(-4px); box-shadow:0 16px 40px rgba(19,18,9,.08);
  border-color:rgba(19,18,9,.18)}
.section--dark .card{background:var(--dark2); border-color:#313131}
.chip{display:grid; place-items:center; width:48px; height:48px; border-radius:var(--r-xl);
  background:rgba(255,106,0,.12); color:var(--primary); font-size:1.5rem}
.chip--blue{background:rgba(30,144,255,.12); color:var(--secondary)}
.grid{display:grid; gap:var(--sp-300)}
@media(min-width:700px){.grid-2{grid-template-columns:repeat(2,1fr)}}
@media(min-width:700px){.grid-4{grid-template-columns:repeat(2,1fr)}}
@media(min-width:1000px){.grid-3{grid-template-columns:repeat(3,1fr)}
  .grid-4{grid-template-columns:repeat(4,1fr)}}

/* service log panel */
.panel{border:1px solid var(--line); border-radius:var(--r-3xl); background:var(--white);
  padding:var(--sp-300); box-shadow:0 24px 60px rgba(19,18,9,.10)}
.panel-head{display:flex; align-items:center; justify-content:space-between; gap:var(--sp-200);
  padding-bottom:var(--sp-200); border-bottom:1px solid var(--line)}
.row{display:grid; grid-template-columns:1fr auto; gap:var(--sp-100); align-items:center;
  padding:var(--sp-200) 0; border-bottom:1px solid var(--line)}
.row:last-child{border-bottom:0; padding-bottom:0}
.tag{font-size:0.75rem; line-height:16px; font-weight:600; padding:var(--sp-25) var(--sp-75);
  border-radius:var(--r-full); background:rgba(30,144,255,.12); color:#1568b8}
.tag--done{background:rgba(255,106,0,.14); color:#a84500}

/* stats */
.stats{display:grid; gap:var(--sp-300); border:1px solid var(--line); border-radius:var(--r-2xl);
  padding:var(--sp-400); background:var(--white)}
@media(min-width:700px){.stats{grid-template-columns:repeat(3,1fr)}}
.stat-n{font-size:2.25rem; line-height:40px; font-weight:600; color:var(--primary)}

/* steps */
.step-n{font-size:0.875rem; line-height:20px; font-weight:600; color:var(--primary)}

/* tagline reveal */
.tagline{font-size:2.25rem; line-height:40px; font-weight:600; max-width:680px;
  letter-spacing:-0.02em; text-wrap:balance}
@media(min-width:768px){.tagline{font-size:3rem; line-height:1}}
@media(min-width:1100px){.tagline{font-size:3.75rem; line-height:1}}
.tagline .w{color:rgba(255,255,255,.30); transition:color .8s var(--ease)}
.tagline .w.on{color:var(--white)}

/* schedule picker */
.tabs{display:flex; flex-wrap:wrap; gap:var(--sp-75)}
.tab{padding:var(--sp-75) var(--sp-100); border:1px solid var(--line); background:var(--white);
  border-radius:var(--r-full); font-family:inherit; font-size:0.875rem; line-height:20px;
  font-weight:600; cursor:pointer; transition:all .5s var(--ease)}
.tab:hover{border-color:var(--ink)}
.tab:active{transform:translateY(1px)}
.tab[aria-selected="true"]{background:var(--ink); color:var(--white); border-color:var(--ink)}
.empty{display:grid; gap:var(--sp-100); justify-items:center; text-align:center;
  padding:var(--sp-600) var(--sp-300); border:1px solid var(--line); border-radius:var(--r-2xl);
  background:var(--surface)}
.empty i{font-size:2.25rem; color:var(--primary)}
.checks li{display:flex; gap:var(--sp-75); align-items:flex-start; padding:var(--sp-50) 0;
  font-size:1rem; line-height:24px}
.checks i{color:var(--primary); font-size:1.25rem; flex:none}

/* quotes */
.quote i.ph-quotes{font-size:1.5rem; color:var(--primary)}
.who{display:flex; align-items:center; gap:var(--sp-100)}
.avatar{display:grid; place-items:center; width:40px; height:40px; border-radius:var(--r-full);
  font-size:0.875rem; line-height:20px; font-weight:600; color:var(--white); flex:none}

/* faq */
.faq{border:1px solid var(--line); border-radius:var(--r-xl); background:var(--white);
  padding:var(--sp-300); transition:border-color .5s var(--ease)}
.faq+.faq{margin-top:var(--sp-100)}
.faq:hover{border-color:rgba(19,18,9,.24)}
.faq summary{display:flex; justify-content:space-between; gap:var(--sp-200); cursor:pointer;
  font-weight:600; font-size:1rem; line-height:24px; list-style:none}
.faq summary::-webkit-details-marker{display:none}
.faq summary i{color:var(--primary); transition:transform .6s var(--ease)}
.faq[open] summary i{transform:rotate(45deg)}
.faq p{margin-top:var(--sp-100); color:var(--muted)}

/* form */
.field{display:grid; gap:var(--sp-50)}
.field label{font-size:0.875rem; line-height:20px; font-weight:600}
.field input,.field select,.field textarea{width:100%; font-family:inherit; font-size:1rem;
  line-height:24px; color:var(--ink); background:var(--white); border:1px solid var(--line);
  border-radius:var(--r-lg); padding:var(--sp-75) var(--sp-100); transition:all .4s var(--ease)}
.field input:hover,.field select:hover,.field textarea:hover{border-color:rgba(19,18,9,.32)}
.field textarea{min-height:96px; resize:vertical}
.err{font-size:0.875rem; line-height:20px; color:#b3300c; display:none}
.field.invalid input,.field.invalid select{border-color:#b3300c}
.field.invalid .err{display:block}
.form-grid{display:grid; gap:var(--sp-200)}
@media(min-width:700px){.form-grid{grid-template-columns:repeat(2,1fr)}
  .form-grid .span-2{grid-column:span 2}}
.skeleton{display:none; gap:var(--sp-100); grid-auto-flow:row}
.skeleton.on{display:grid}
.sk{height:16px; border-radius:var(--r-lg); background:#e9e8e2; animation:pulse 1.2s var(--ease) infinite}
.sk:nth-child(2){width:72%} .sk:nth-child(3){width:46%}
@keyframes pulse{50%{background:#f4f3ee}}
.done{display:none; gap:var(--sp-75); align-items:flex-start}
.done.on{display:flex}
.done i{color:var(--primary); font-size:1.5rem; flex:none}

/* footer */
.footer{background:var(--dark); color:var(--white); padding:var(--sp-700) 0 var(--sp-400)}
.footer a{text-decoration:none; color:#b9b8b2; transition:color .4s var(--ease)}
.footer a:hover{color:var(--white)}
.foot-grid{display:grid; gap:var(--sp-500)}
@media(min-width:800px){.foot-grid{grid-template-columns:1.4fr 1fr 1fr 1fr}}
.foot-grid h3{font-size:0.75rem; line-height:16px; letter-spacing:.14em; text-transform:uppercase;
  color:#8f8e88; margin-bottom:var(--sp-100)}
.foot-grid li+li{margin-top:var(--sp-75)}
.rule{border-top:1px solid #313131; margin-top:var(--sp-600); padding-top:var(--sp-300);
  display:flex; flex-wrap:wrap; gap:var(--sp-200); justify-content:space-between;
  font-size:0.875rem; line-height:20px; color:#8f8e88}
.legal{padding:var(--sp-600) 0}
.legal h3{margin-bottom:var(--sp-75)}

/* scroll reveal */
.rise{opacity:0; transform:translateY(64px); filter:blur(12px);
  transition:opacity .9s var(--ease), transform .9s var(--ease), filter .9s var(--ease)}
.rise.in{opacity:1; transform:translateY(0); filter:blur(0)}
@media(prefers-reduced-motion:reduce){
  .rise{opacity:1; transform:none; filter:none; transition:none}
  *{animation-duration:.01ms !important; transition-duration:.01ms !important}
}
