{"path": "styles.css", "content": "/* Doggy Duty, LLC - landing page styles */
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap');

:root{
  --s25:2px; --s50:4px; --s75:8px; --s100:12px; --s200:16px; --s300:24px;
  --s400:32px; --s500:40px; --s600:48px; --s700:64px; --s800:80px; --s900:96px;
  --ink:#131209; --muted:#5c5b55; --line:#e4e3dd; --surface:#f6f5f0;
  --white:#ffffff; --primary:#ff6a00; --secondary:#1e90ff; --dark:#131209;
  --ease:cubic-bezier(0.32,0.72,0,1);
