}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:'Poppins',sans-serif;font-weight:400;background:var(--white);
  color:var(--ink);font-size:1rem;line-height:24px;text-wrap:pretty;
  -webkit-font-smoothing:antialiased;
}
h1,h2,h3,h4{font-weight:600;text-wrap:balance;line-height:1.15}
img,svg{display:block;max-width:100%}
a{color:inherit;text-decoration:none}
li{list-style:none}
:focus-visible{outline:2px solid var(--secondary);outline-offset:2px;border-radius:var(--r-lg)}

.container{width:100%;max-width:1160px;margin:0 auto;padding:0 var(--s300)}
.section{padding:var(--s700) 0}
.section.alt{background:var(--surface)}
.section.dark{background:var(--dark);color:var(--white)}
.skip{position:absolute;left:var(--s200);top:-64px;background:var(--ink);color:var(--white);
  padding:var(--s75) var(--s100);border-radius:var(--r-full);font-size:.875rem;line-height:20px;
  z-index:60;transition:top .3s var(--ease)}
.skip:focus{top:var(--s200)}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;gap:var(--s75);padding:var(--s75) var(--s100);
  border-radius:var(--r-full);font-size:1rem;line-height:24px;font-weight:600;border:1px solid transparent;
  cursor:pointer;font-family:inherit;transition:all .7s var(--ease)}
.btn i{font-size:1.125rem}
.btn-primary{background:var(--primary);color:var(--white)}
.btn-primary:hover{background:#e65f00;transform:translateY(-1px)}
.btn-primary:active{transform:scale(.98)}
.btn-line{background:transparent;color:var(--ink);border-color:var(--line)}
.btn-line:hover{background:var(--surface);transform:translateY(-1px)}
.btn-line:active{transform:scale(.98)}
.btn-sm{font-size:.875rem;line-height:20px}
.btn[disabled]{opacity:.55;cursor:not-allowed;transform:none}
.textlink{font-size:.875rem;line-height:20px;font-weight:500;color:var(--muted);
  display:inline-flex;align-items:center;gap:var(--s50);transition:color .7s var(--ease)}
.textlink:hover{color:var(--primary)}

/* ---------- navigation ---------- */
.nav{position:fixed;top:var(--s300);left:0;right:0;z-index:50;display:flex;justify-content:center;
  pointer-events:none}
