  max-width:calc(100% - 32px);background:rgba(255,255,255,.82);backdrop-filter:blur(24px) saturate(1.6);
  border:1px solid var(--line);border-radius:var(--r-full);padding:var(--s75) var(--s100);
  box-shadow:0 8px 32px rgba(19,18,9,.08)}
.brand{display:flex;align-items:center;gap:var(--s75);font-weight:600;font-size:1rem;line-height:24px;
  padding-left:var(--s75)}
.brand-mark{width:32px;height:32px;border-radius:var(--r-full);background:var(--primary);color:var(--white);
  display:grid;place-items:center;font-size:1.125rem}
.navlinks{display:flex;align-items:center;gap:var(--s300)}
.navlinks a{font-size:.875rem;line-height:20px;font-weight:500;color:var(--muted);
  transition:color .7s var(--ease)}
.navlinks a:hover{color:var(--ink)}
.navlinks a.is-current{color:var(--ink);font-weight:600}
.burger{display:none;width:32px;height:32px;border:1px solid var(--line);border-radius:var(--r-full);
  background:var(--white);position:relative;cursor:pointer;transition:all .7s var(--ease)}
.burger span{position:absolute;left:50%;width:14px;height:2px;background:var(--ink);border-radius:var(--r-full);
  transform:translateX(-50%);transition:all .7s var(--ease)}
.burger span:nth-child(1){top:13px}
.burger span:nth-child(2){top:19px}
.burger[aria-expanded="true"] span:nth-child(1){top:16px;transform:translateX(-50%) rotate(45deg)}
.burger[aria-expanded="true"] span:nth-child(2){top:16px;transform:translateX(-50%) rotate(-45deg)}
.overlay{position:fixed;inset:0;z-index:40;background:rgba(255,255,255,.8);
  backdrop-filter:blur(64px) saturate(1.4);display:grid;place-items:center;
  opacity:0;visibility:hidden;transition:all .7s var(--ease)}
.overlay.open{opacity:1;visibility:visible}
.overlay ul{display:grid;gap:var(--s300);text-align:center}
.overlay a{display:block;font-size:1.875rem;line-height:36px;font-weight:600;
  transform:translateY(48px);opacity:0;transition:all .8s var(--ease)}
.overlay.open a{transform:translateY(0);opacity:1}
.overlay li:nth-child(1) a{transition-delay:.1s}
.overlay li:nth-child(2) a{transition-delay:.15s}
.overlay li:nth-child(3) a{transition-delay:.2s}
.overlay li:nth-child(4) a{transition-delay:.25s}
.overlay li:nth-child(5) a{transition-delay:.3s}

/* ---------- hero ---------- */
.hero{padding:var(--s900) 0 var(--s700)}
