  font-weight:500;color:var(--primary);background:rgba(255,106,0,.09);border:1px solid rgba(255,106,0,.22);
  border-radius:var(--r-full);padding:var(--s50) var(--s100);margin-bottom:var(--s300)}
.hero-h{max-width:680px;font-size:2.25rem;line-height:40px;
  background:linear-gradient(90deg,#000000,#666666);-webkit-background-clip:text;background-clip:text;
  color:transparent}
.lede{max-width:680px;margin-top:var(--s300);font-size:1.125rem;line-height:28px;color:var(--muted)}
.cta-row{display:flex;flex-wrap:wrap;align-items:center;gap:var(--s300);margin-top:var(--s400)}
.proofline{display:flex;align-items:center;gap:var(--s75);margin-top:var(--s400);
  font-size:.875rem;line-height:20px;color:var(--muted)}
.proofline i{color:var(--primary);font-size:1.125rem}

/* ---------- panels, cards ---------- */
.panel{background:var(--white);border:1px solid var(--line);border-radius:var(--r-3xl);padding:var(--s400);
  box-shadow:0 16px 48px rgba(19,18,9,.07)}
.panel-head{display:flex;align-items:center;justify-content:space-between;gap:var(--s200);
  padding-bottom:var(--s200);border-bottom:1px solid var(--line)}
.panel-head h3{font-size:1rem;line-height:24px}
.panel-head span{font-size:.75rem;line-height:16px;color:var(--muted)}
.log-row{display:flex;align-items:center;justify-content:space-between;gap:var(--s200);
  padding:var(--s200) 0;border-bottom:1px solid var(--line)}
.log-row:last-child{border-bottom:0;padding-bottom:0}
.log-row p{font-size:.875rem;line-height:20px;font-weight:500}
.log-row small{display:block;font-size:.75rem;line-height:16px;color:var(--muted);font-weight:400}
.chip{flex:none;font-size:.75rem;line-height:16px;font-weight:500;border-radius:var(--r-full);
