.chip.blue{background:rgba(30,144,255,.12);color:#0f5fad}

.grid2,.grid3,.grid4{display:grid;gap:var(--s300)}
.card{background:var(--white);border:1px solid var(--line);border-radius:var(--r-2xl);padding:var(--s400)}
.section.alt .card{background:var(--white)}
.section.dark .card{background:#1f1f1f;border-color:#313131}
