.card ul{margin-top:var(--s200);display:grid;gap:var(--s75)}
.card ul li{display:flex;gap:var(--s75);font-size:.875rem;line-height:20px;color:var(--muted)}
.card ul i{color:var(--primary);font-size:1rem;flex:none;margin-top:var(--s25)}

.h2{font-size:1.875rem;line-height:36px;max-width:680px}
.sub{margin-top:var(--s200);max-width:680px;font-size:1.125rem;line-height:28px;color:var(--muted)}
.head-block{margin-bottom:var(--s600)}

/* ---------- stats ---------- */
.stats{display:grid;gap:var(--s300);grid-template-columns:repeat(2,1fr)}
.stat{border:1px solid var(--line);border-radius:var(--r-2xl);padding:var(--s400);background:var(--white)}
.stat b{display:block;font-size:1.875rem;line-height:36px;font-weight:600}
.stat span{font-size:.875rem;line-height:20px;color:var(--muted)}

/* ---------- tagline reveal ---------- */
.tagline{max-width:680px;font-size:2.25rem;line-height:1.2;font-weight:600}
.word{color:rgba(255,255,255,.28);transition:color .8s var(--ease)}
.word.on{color:#ffffff}

/* ---------- benefits ---------- */
.blist{display:grid;gap:var(--s300)}
.blist li{display:flex;gap:var(--s200);border-bottom:1px solid var(--line);padding-bottom:var(--s300)}
.blist li:last-child{border-bottom:0;padding-bottom:0}
.blist i{color:var(--primary);font-size:1.5rem;flex:none}
.blist b{font-weight:600}
.blist p{font-size:1rem;line-height:24px;color:var(--muted)}

/* ---------- steps ---------- */
.step-num{width:40px;height:40px;border-radius:var(--r-full);background:var(--primary);color:var(--white);
  display:grid;place-items:center;font-weight:600;font-size:1rem;margin-bottom:var(--s300)}

/* ---------- schedule picker ---------- */
.picker{display:flex;flex-wrap:wrap;gap:var(--s100);margin-bottom:var(--s300)}
.picker button{font-family:inherit;font-size:.875rem;line-height:20px;font-weight:600;
  padding:var(--s75) var(--s100);border-radius:var(--r-full);border:1px solid var(--line);
  background:var(--white);color:var(--muted);cursor:pointer;transition:all .7s var(--ease)}
.picker button:hover{color:var(--ink);transform:translateY(-1px)}
.picker button:active{transform:scale(.98)}
.picker button.on{background:var(--ink);color:var(--white);border-color:var(--ink)}
.pane{border:1px solid var(--line);border-radius:var(--r-2xl);background:var(--white);padding:var(--s400);
  min-height:200px}
.pane.empty{display:grid;place-items:center;text-align:center;color:var(--muted)}
.pane.empty i{font-size:2.25rem;color:var(--primary);margin-bottom:var(--s100)}
.pane h3{font-size:1.25rem;line-height:28px;margin-bottom:var(--s200)}
.pane ul{display:grid;gap:var(--s75)}
.pane li{display:flex;gap:var(--s75);font-size:1rem;line-height:24px;color:var(--muted)}
.pane li i{color:var(--primary);flex:none;margin-top:var(--s25)}

/* ---------- testimonials ---------- */
.quote p{font-size:1.125rem;line-height:28px}
.who{display:flex;align-items:center;gap:var(--s100);margin-top:var(--s300)}
.avatar{width:40px;height:40px;border-radius:var(--r-full);display:grid;place-items:center;
  font-size:.875rem;font-weight:600;color:var(--white);flex:none}
.who b{display:block;font-size:.875rem;line-height:20px}
.who span{font-size:.75rem;line-height:16px;color:var(--muted)}
.stars{color:var(--primary);font-size:1rem;margin-bottom:var(--s200)}

/* ---------- faq ---------- */
.faq{display:grid;gap:var(--s100);max-width:800px}
.faq details{border:1px solid var(--line);border-radius:var(--r-xl);background:var(--white);
  padding:var(--s200) var(--s300);transition:all .7s var(--ease)}
.faq details[open]{background:var(--surface)}
.faq summary{display:flex;align-items:center;justify-content:space-between;gap:var(--s200);
  cursor:pointer;font-weight:600;font-size:1rem;line-height:24px;list-style:none}
.faq summary::-webkit-details-marker{display:none}
.faq summary i{color:var(--primary);transition:transform .7s var(--ease)}
.faq details[open] summary i{transform:rotate(45deg)}
.faq p{margin-top:var(--s100);color:var(--muted);font-size:1rem;line-height:24px}

/* ---------- form ---------- */
.form{display:grid;gap:var(--s200)}
.field{display:grid;gap:var(--s50)}
.field label{font-size:.875rem;line-height:20px;font-weight:500}
.field input,.field select,.field textarea{font-family:inherit;font-size:1rem;line-height:24px;
  color:var(--ink);background:var(--white);border:1px solid var(--line);border-radius:var(--r-lg);
  padding:var(--s75) var(--s100);width:100%;transition:border-color .7s var(--ease)}
.field textarea{min-height:96px;resize:vertical}
.field input:hover,.field textarea:hover,.field select:hover{border-color:#c9c8c0}
.err{font-size:.75rem;line-height:16px;color:#b3261e;display:none}
.field.invalid input,.field.invalid select{border-color:#b3261e}
.field.invalid .err{display:block}
.skel{display:none;gap:var(--s100)}
.skel div{height:16px;border-radius:var(--r-lg);background:var(--line);animation:pulse 1.4s var(--ease) infinite}
.skel div:nth-child(2){width:70%}
.skel div:nth-child(3){width:45%}
@keyframes pulse{0%,100%{background:var(--line)}50%{background:#f0efe9}}
.ok{display:none;gap:var(--s75);align-items:flex-start;font-size:1rem;line-height:24px}
.ok i{color:var(--primary);font-size:1.25rem;flex:none}
.is-sending .form{display:none}
.is-sending .skel{display:grid}
.is-done .form,.is-done .skel{display:none}
.is-done .ok{display:flex}
.fineprint{font-size:.75rem;line-height:16px;color:var(--muted)}

/* ---------- footer ---------- */
footer{background:#181818;color:var(--white);padding:var(--s700) 0 var(--s400)}
footer a{color:rgba(255,255,255,.72);transition:color .7s var(--ease)}
footer a:hover{color:var(--white)}
.fgrid{display:grid;gap:var(--s500)}
.fcol h4{font-size:.875rem;line-height:20px;margin-bottom:var(--s200)}
.fcol ul{display:grid;gap:var(--s75);font-size:.875rem;line-height:20px}
.socials{display:flex;gap:var(--s75)}
.socials a{width:40px;height:40px;border:1px solid #313131;border-radius:var(--r-full);display:grid;
  place-items:center;font-size:1.125rem}
.socials a:hover{background:#272727}
.legal{border:1px solid #272727;border-radius:var(--r-2xl);padding:var(--s300);margin-top:var(--s600)}
.legal h4{font-size:1rem;line-height:24px;margin-bottom:var(--s75)}
.legal p{font-size:.75rem;line-height:16px;color:rgba(255,255,255,.66)}
.legal div+div{margin-top:var(--s300)}
.fine{margin-top:var(--s400);padding-top:var(--s300);border-top:1px solid #272727;
  display:flex;flex-wrap:wrap;gap:var(--s200);justify-content:space-between;
  font-size:.75rem;line-height:16px;color:rgba(255,255,255,.66)}

/* ---------- scroll reveal ---------- */
.reveal{opacity:0;transform:translateY(64px);filter:blur(12px);
  transition:opacity .8s var(--ease),transform .8s var(--ease),filter .8s var(--ease)}
.reveal.in{opacity:1;transform:translateY(0);filter:blur(0)}
@media (prefers-reduced-motion:reduce){
  *{transition-duration:.01ms!important;animation:none!important}
  .reveal{opacity:1;transform:none;filter:none}
  .word{color:#fff}
}

/* ---------- responsive ---------- */
@media (max-width:767px){
  .navlinks,.pill .btn{display:none}
  .burger{display:block}
  .pill{gap:var(--s200);justify-content:space-between;width:calc(100% - 32px)}
}
@media (min-width:768px){
  .section{padding:var(--s900) 0}
  .hero{padding:160px 0 var(--s900)}
  .hero-h{font-size:3rem;line-height:1.08}
  .h2{font-size:2.25rem;line-height:40px}
  .tagline{font-size:3rem}
  .grid2{grid-template-columns:repeat(2,1fr)}
  .grid3{grid-template-columns:repeat(3,1fr)}
  .grid4{grid-template-columns:repeat(2,1fr)}
  .stats{grid-template-columns:repeat(4,1fr)}
  .fgrid{grid-template-columns:1.4fr 1fr 1fr 1fr}
  .overlay a{font-size:2.25rem;line-height:40px}
}
@media (min-width:1024px){
  .hero-grid{grid-template-columns:1.05fr .95fr;align-items:center;gap:var(--s700)}
  .hero-h{font-size:3.75rem}
  .tagline{font-size:3.75rem}
  .grid4{grid-template-columns:repeat(4,1fr)}
  .split{display:grid;grid-template-columns:1fr 1fr;gap:var(--s700);align-items:start}
}
"}

{"path": "script.js", "content": "/* Doggy Duty, LLC — interactions
   Motion: custom easing only. Reveals: IntersectionObserver only. */

(function () {
  'use strict';

  var EASE = 'cubic-bezier(0.32,0.72,0,1)';
  var $ = function (sel, root) { return (root || document).querySelector(sel); };
  var $$ = function (sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); };

  /* ---------------------------------------------------------------
     1. Island nav: hamburger morph + full screen glass overlay
  ---------------------------------------------------------------- */
  var burger = $('.burger');
  var overlay = $('.overlay');

  function setMenu(open) {
    if (!overlay || !burger) return;
    overlay.classList.toggle('open', open);
    burger.classList.toggle('is-open', open);
    burger.setAttribute('aria-expanded', open ? 'true' : 'false');
    burger.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    document.documentElement.style.overflow = open ? 'hidden' : '';
    if (open) {
      var first = $('a, button', overlay);
      if (first) { window.setTimeout(function () { first.focus(); }, 260); }
    }
  }

  if (burger) {
    burger.addEventListener('click', function () {
      setMenu(!(overlay && overlay.classList.contains('open')));
    });
  }
  if (overlay) {
    $$('a, button', overlay).forEach(function (el) {
      el.addEventListener('click', function () { setMenu(false); });
    });
  }
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') { setMenu(false); }
  });

  /* ---------------------------------------------------------------
     2. Scroll reveals: heavy fade up with blur
  ---------------------------------------------------------------- */
  var revealables = $$('.reveal');
  if ('IntersectionObserver' in window && revealables.length) {
    var revealObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('in');
          revealObserver.unobserve(entry.target);
        }
      });
    }, { rootMargin: '0px 0px -12% 0px', threshold: 0.12 });
    revealables.forEach(function (el) { revealObserver.observe(el); });
  } else {
    revealables.forEach(function (el) { el.classList.add('in'); });
  }

  /* ---------------------------------------------------------------
     3. Tagline reveal: each word warms up as it crosses the line
  ---------------------------------------------------------------- */
  $$('.tagline').forEach(function (block) {
    var lines = $$('.tagline-line', block);
    var hosts = lines.length ? lines : [block];

    hosts.forEach(function (host) {
      if ($('.word', host)) return; // already split
      var raw = host.textContent.replace(/\s+/g, ' ').trim();
      host.textContent = '';
      raw.split(' ').forEach(function (word, i) {
        var span = document.createElement('span');
        span.className = 'word';
        span.textContent = word;
        span.style.transitionDelay = (i % 8) * 40 + 'ms';
        span.style.transitionTimingFunction = EASE;
        host.appendChild(span);
        host.appendChild(document.createTextNode(' '));
      });
    });

    var words = $$('.word', block);
    if (!words.length) return;

    if (!('IntersectionObserver' in window)) {
      words.forEach(function (w) { w.classList.add('on'); });
      return;
    }

    var wordObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('on');
          wordObserver.unobserve(entry.target);
        }
      });
    }, { rootMargin: '-45% 0px -40% 0px', threshold: 0 });

    words.forEach(function (w) { wordObserver.observe(w); });

    // Safety net: if the block is fully passed, warm any leftovers.
    var tail = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.boundingClientRect.bottom < 0) {
          words.forEach(function (w) { w.classList.add('on'); });
        }
      });
    }, { threshold: 0 });
    tail.observe(block);
  });

  /* ---------------------------------------------------------------
     4. Schedule picker: empty state until a plan is chosen
  ---------------------------------------------------------------- */
  var picker = $('.picker');
  var pane = $('.pane');

  var PLANS = {
    weekly: {
      title: 'Once per week',
      lead: 'The most common plan for single family and townhome communities.',
      items: [
        'Every station emptied and wiped down on the same weekday',
        'Fresh bag rolls loaded, spares left inside the triple storage box',
        'Loose waste picked up inside a 15 foot radius of each station',
        'Photo log of every station emailed to the manager after the route'
      ]
    },
    twice: {
      title: 'Twice per week',
      lead: 'Built for dense condo and apartment properties with heavy dog traffic.',
      items: [
        'Two servicing days, usually Monday and Thursday',
        'Bag rolls counted and topped off at both visits',
        'Common lawns, breezeways and dog runs swept for missed waste',
        'Overflow bins swapped out before weekend showings'
      ]
    },
    valet: {
      title: 'Nightly valet trash',
      lead: 'Door pickup five nights per week, paired with your station service.',
      items: [
        'Collection outside every resident door between 7:00 pm and 10:00 pm',
        'Uniformed technicians with photo identification and route tracking',
        'Violation notes for improperly bagged trash, sent to the office',
        'Bulk item reporting so nothing sits by the compactor for days'
      ]
    }
  };

  function renderPlan(key) {
    if (!pane) return;
    var plan = PLANS[key];
    if (!plan) return;
    pane.classList.remove('empty');
    var list = plan.items.map(function (i) {
      return '<li><i class="ph ph-check-circle" aria-hidden="true"></i><span>' + i + '</span></li>';
    }).join('');
    pane.innerHTML =
      '<h3>' + plan.title + '</h3>' +
      '<p>' + plan.lead + '</p>' +
      '<ul class="pane-list">' + list + '</ul>' +
      '<p class="fine">Quoted per station and per door after a short walk of the property. ' +
      'No charge for the visit or the quote.</p>';
  }

  if (picker) {
    $$('button', picker).forEach(function (btn) {
      btn.addEventListener('click', function () {
        $$('button', picker).forEach(function (b) {
          b.classList.remove('on');
          b.setAttribute('aria-pressed', 'false');
        });
        btn.classList.add('on');
        btn.setAttribute('aria-pressed', 'true');
        renderPlan(btn.getAttribute('data-plan'));
      });
    });
  }

  /* ---------------------------------------------------------------
     5. Quote form: inline validation, skeleton loading, success
  ---------------------------------------------------------------- */
  var form = $('form[data-quote]') || $('main form');

  function fieldWrap(input) {
    return input.closest('.field') || input.parentNode;
  }

  function showError(input, message) {
    var wrap = fieldWrap(input);
    var msg = $('.err', wrap);
    if (!msg) {
      msg = document.createElement('p');
      msg.className = 'err';
      wrap.appendChild(msg);
    }
    msg.textContent = message;
    msg.hidden = false;
    input.setAttribute('aria-invalid', 'true');
  }

  function clearError(input) {
    var wrap = fieldWrap(input);
    var msg = $('.err', wrap);
    if (msg) { msg.textContent = ''; msg.hidden = true; }
    input.removeAttribute('aria-invalid');
  }

  function validate(input) {
    var value = (input.value || '').trim();
    var type = input.getAttribute('type');
    if (input.hasAttribute('required') && !value) {
      showError(input, 'This field is required.');
      return false;
    }
    if (type === 'email' && value && !/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(value)) {
      showError(input, 'Enter a valid email address, like manager@yourcommunity.com');
      return false;
    }
    if (type === 'tel' && value && value.replace(/\D/g, '').length < 10) {
      showError(input, 'Enter a 10 digit phone number so we can call you back.');
      return false;
    }
    clearError(input);
    return true;
  }

  if (form) {
    var fields = $$('input, select, textarea', form);
    fields.forEach(function (input) {
      input.addEventListener('blur', function () { validate(input); });
      input.addEventListener('input', function () {
        if (input.getAttribute('aria-invalid') === 'true') { validate(input); }
      });
    });

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var ok = true;
      fields.forEach(function (input) { if (!validate(input)) { ok = false; } });
      if (!ok) {
        var bad = $('[aria-invalid="true"]', form);
        if (bad) { bad.focus(); }
        return;
      }

      var button = $('button[type="submit"], .btn-primary', form);
      var skeleton = $('.skel', form);
      if (button) {
        button.disabled = true;
        button.dataset.label = button.textContent;
        button.textContent = 'Sending your request';
      }
      if (skeleton) { skeleton.hidden = false; }

      window.setTimeout(function () {
        if (skeleton) { skeleton.hidden = true; }
        var name = ($('[name="name"]', form) || {}).value || '';
        var first = name.trim().split(' ')[0];
        var done = $('.ok', form) || document.createElement('div');
        done.className = 'ok';
        done.setAttribute('role', 'status');
        done.innerHTML =
          '<i class="ph ph-paw-print" aria-hidden="true"></i>' +
          '<p><strong>Request received' + (first ? ', ' + first : '') + '.</strong> ' +
          'A route manager replies within one business day, usually the same afternoon. ' +
          'Need it sooner, call (863) 399 5176.</p>';
        form.replaceChildren(done);
        done.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 900);
    });
  }

  /* ---------------------------------------------------------------
     6. Footer year
  ---------------------------------------------------------------- */
  var year = $('[data-year]');
  if (year) { year.textContent = new Date().getFullYear(); }
})();
"}
